@startuml

class InsuranceCompany {
  + CompanyName : string
  + RegistrationNumber : string
}

class Policy {
  + PolicyType : string
  + CoverageAmount : double
}

class CarLiabilityPolicy {
  + VehicleDetails : string
}

class LifePolicy {
  + BeneficiaryName : string
}

class RiskPolicy {
  + RiskDescription : string
}

class Customer {
  + CustomerName : string
  + CustomerId : int
}

class Contract {
  + ContractId : int
  + SigningDate : date
  + Status : string
}

InsuranceCompany "1" -- "*" Policy
InsuranceCompany "1" -- "*" Customer
Customer "1" -- "*" Contract
Contract "*" -- "1" Policy

CarLiabilityPolicy --|> Policy
LifePolicy --|> Policy
RiskPolicy --|> Policy

@enduml

